#pragma once
#include "kernels/transient_structural.hpp"
inline void dynamic_json(std::ostream&out,const dynamics::Model&m,const dynamics::Result&r,const std::string&sha){
    const auto&h=r.history;const auto&o=m.options;
    out<<"\"dynamic_schema\":1,\"job_sha256\":\""<<sha<<"\",\"complete\":true,\"converged\":true,\"solver\":\"Newmark_average_acceleration\",\"newmark_beta\":0.25,\"newmark_gamma\":0.5,\"alpha_mass_per_s\":"<<o.alpha_mass<<",\"beta_stiffness_s\":"<<o.beta_stiffness<<",\"time_step_s\":"<<o.dt<<",\"steps\":"<<o.steps<<",\"linear_iteration_limit\":"<<o.linear_iterations<<",\"linear_tolerance\":"<<o.tolerance<<",\"wall_limit_s\":"<<o.seconds<<",\"displacement_units\":\"m\",\"velocity_units\":\"m/s\",\"acceleration_units\":\"m/s^2\",\"energy_units\":\"J\",\"dof_order\":\"3*node+[x,y,z]\",\"total_mass_kg\":"<<r.total_mass<<",\"active_dof_ids\":[";
    for(size_t i=0;i<r.active_dofs.size();++i){if(i)out<<',';out<<r.active_dofs[i];}out<<"],\"nodes\":";json(out,m.fem.structure.nodes);out<<",\"elements\":[";
    for(size_t i=0;i<m.fem.structure.elements.size();++i){if(i)out<<',';auto&t=m.fem.structure.elements[i];out<<'['<<t.nodes[0]<<','<<t.nodes[1]<<','<<t.nodes[2]<<','<<t.nodes[3]<<']';}
    out<<"],\"materials\":[";for(size_t i=0;i<m.fem.density.size();++i){if(i)out<<',';auto material=m.fem.structure.elements[i].material;out<<"{\"E_Pa\":"<<material.E<<",\"nu\":"<<material.nu<<",\"density_kg_m3\":"<<m.fem.density[i]<<'}';}
    out<<"],\"assembly_ms\":"<<r.assembly_ms<<",\"effective_setup_ms\":"<<h.setup_ms<<",\"integration_ms\":"<<h.integration_ms<<",\"effective_system_setups\":"<<h.effective_setups<<",\"linear_iterations\":"<<h.linear_iterations<<",\"max_linear_residual\":"<<h.max_linear_residual<<",\"max_equilibrium_residual\":"<<h.max_equilibrium_residual<<",\"max_energy_balance_J\":"<<h.max_energy_balance<<",\"stiffness_nnz\":"<<r.stiffness_nnz<<",\"mass_nnz\":"<<r.mass_nnz<<",\"selected_preconditioner\":\""<<h.preconditioner<<"\",\"preconditioner_fallback\":\""<<h.fallback<<"\",\"output_steps\":[";for(size_t i=0;i<o.outputs.size();++i){if(i)out<<',';out<<o.outputs[i];}out<<"],\"frame_count\":"<<h.frames.size()<<",\"frames\":[";
    for(size_t j=0;j<h.frames.size();++j){if(j)out<<',';const auto&f=h.frames[j];out<<"{\"step\":"<<f.step<<",\"time_s\":"<<f.time<<",\"kinetic_energy_J\":"<<f.kinetic<<",\"elastic_energy_J\":"<<f.elastic<<",\"damping_dissipation_J\":"<<f.dissipation<<",\"external_work_J\":"<<f.work<<",\"energy_balance_J\":"<<f.balance<<",\"equilibrium_residual\":"<<f.residual;
        for(int field=0;field<3;++field){const auto&v=field==0?f.u:field==1?f.v:f.a;std::vector<double>full(m.fem.structure.nodes.size()*3);for(size_t i=0;i<r.active_dofs.size();++i)full[r.active_dofs[i]]=v[i];out<<(field==0?",\"displacement_flat\":" : field==1?",\"velocity_flat\":" : ",\"acceleration_flat\":");json(out,full);}out<<'}';}
    out<<']';
}
